		value, ok := vm.scopedConstantValue(receiver, name)
		if !ok {
			value = vm.sendBypassVisibility(receiver, "const_missing", []*object.EmeraldValue{{Type: object.ValueSymbol, Data: name, Class: core.R.Classes["Symbol"]}})
		}
