		val := core.R.NilVal
		if vm.sp > frame.Bp {
			val = vm.pop()
		}
		if target > 0 {
			if vm.routeBreakThroughEnsure(frame, val, int(target)) {
				return nil
			}
			vm.push(val)
			frame.Ip = target - 1
			return nil
		}
		if frame.WhileEnd >= 0 {
			if vm.routeBreakThroughEnsure(frame, val, frame.WhileEnd) {
				return nil
			}
			vm.push(val)
			frame.Ip = frame.WhileEnd - 1
			return nil
		}
